import React, {useState, useEffect} from 'react'
import { Deposit } from '../components/Deposit/Deposit'
import { Strategys } from '../components/Strategys/Strategys'
import { useSelector } from "react-redux";
import styles from "./Account.module.css"
import { AIRecommendations } from '../components/AIRecommendations/AIRecommendations'
import { Reports } from '../components/Reports'
import { AccountModal } from '../components/AccountModal'


export const Account = () => {

  const [showModal, setShowModal] = useState(false);
  const [accountNumber, setAccountNumber] = useState('');
  const userData = useSelector((state) => state.userData?.data)

  useEffect(() => {
    if (!userData.realAccountNumber) {
      setShowModal(true);
    } else {
      setAccountNumber(userData.realAccountNumber);
    }
  }, []);

  const handleSaveAccount = (number) => {
    setAccountNumber(number);
    setShowModal(false);
  };

  const handleCloseModal = () => {
    setShowModal(false);
  };


  return (
    <>
      {showModal && (
        <AccountModal
          title={'AI Trading приветствует Вас в личном кабинете'}
          description={
            <>
              <p style={{ fontWeight: '700', fontSize: '16px' }}>
                Предлагаем ознакомиться с функционалом личного кабинета:
              </p>
              <p style={{ paddingLeft: '16px', fontWeight: '400', fontSize: '16px' }}>
                <strong>1. Ваш аккаунт</strong> — вся важная информация о Вашем аккаунте
              </p>
              <p style={{ paddingLeft: '16px', fontWeight: '400', fontSize: '16px' }}>
                <strong>2. Демо-счет</strong> — статистика Вашего пробного счета. Для привязки счета к личному кабинету введите номер Вашего счета в соответствующей вкладке
              </p>
               <p style={{ paddingLeft: '16px', fontWeight: '400', fontSize: '16px' }}>
                <strong>3. Торговля</strong> — статистика Вашего основного счета. Для привязки счета к личному кабинету введите номер Вашего счета в соответствующей вкладке
              </p>
               <p style={{ paddingLeft: '16px', fontWeight: '400', fontSize: '16px' }}>
                <strong>4. Стратегии</strong> — имитация торговли с Вашими индивидуальными настройками
              </p>
               <p style={{ paddingLeft: '16px', fontWeight: '400', fontSize: '16px' }}>
                <strong>5. Партнерская программа</strong> — вся необходимая информации о партнерской программе
              </p>
              {/* Горизонтальная линия */}
              <hr style={{ border: 'none', borderBottom: '2px solid #5B5B5B', marginTop: '20px' }} />
              
              <p style={{ fontWeight: '700', fontSize: '16px' }}>
                <strong>Мы работаем с брокером RoboForex. <p style={{ marginTop: 0, }}>Если у Вас еще нет аккаунта у брокера — пожалуйста, зарегистрируйтесь</p></strong>
              </p>
            </>
          }
          inputField={false}
          firstButton={'Пропустить '}
          secondButton={'Создать аккаунт'}
          onSave={handleSaveAccount}
          onClose={handleCloseModal}
          accountType={'real'}
        />
      )}
      <h1 className={styles.title}>
        Ваш аккаунт
      </h1>
      <Deposit statistics={false}/>
      <Strategys/>
      <AIRecommendations/>
      <Reports/>
    </>
  )
}
