import React from 'react'
import { useSelector, useDispatch } from "react-redux";
import { logout } from "../../../redux/slices/loginSlice";
import { Link } from "react-router-dom";
import styles from "./DashboardHeader.module.css"

export const DashboardHeader = () => {
  const isAuthenticated = useSelector((state) => state.login.isAuthenticated);
  const user = useSelector((state) => state.login.user)

  const dispatch = useDispatch();

    // Обработчик выхода
    const handleLogout = () => {
      if (isAuthenticated) {
        dispatch(logout());
      }
    };

  return (
    <div className={`${styles.header}`}>
      <div className={`${styles.container}`}>
        <div className={styles.companyIdentity}>
          <div className={styles.logo}></div>
          <span className={styles.brandName}>AI Trading</span>
        </div>
        {isAuthenticated ? <div className={styles.userInformation}>
          <div className={styles.userPhoto}>
            <img src="/icon/userPhoto.svg" alt="userPhoto" />
          </div>
          <h3 className={styles.userName}>{user.name}</h3>
        </div> : null}
        
      </div>
      <div className={styles.mainMenu}>
                {/* Меню навигации */}
        <nav className={styles.navigation}>
          {!user ? (
            <>
            <Link to="/" className={styles.navLink}>главная</Link>
            <Link to="/" className={styles.navLink}>трейды</Link>
            <Link to="/" className={styles.navLink}>технологии</Link>
            <Link to="/" className={styles.navLink}>стратегии</Link>
            <Link to="/" className={styles.navLink}>безопасность</Link>
            <Link to="/" className={styles.navLink}>подключиться</Link>
            <Link to="/" className={styles.navLink}>партнерская программа</Link>
            <Link to="/" className={styles.navLink}>инвестировать</Link>
            </> 
          )
            : null 
        }

          {/* Другие ссылки по мере необходимости */}
        </nav>
        {isAuthenticated ?
        <>
          {/* Кнопка выхода */}
          <button className={styles.loginButton} onClick={handleLogout}>
            выйти
          </button> {/* временное заменю на компонент */} 
        </> : null}
      </div> 
    </div>
  )
}
