import React, { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";
import { useSelector, useDispatch } from "react-redux";
import { logout } from "../../../../redux/slices/loginSlice";
import { DashboardHeader } from "../../../headers/DashboardHeader/DashboardHeader";
import styles from "./RegularUser.module.css"
import { DashboardLayout } from "../../../layouts/DashboardLayout/DashboardLayout";
import { Sidebar } from "../../../dashboard/Sidebar";

import {Account} from "../../sections/Account/Account";
import {Demo} from "../../sections/Demo";
import {Trade} from "../../sections/Trade";
import {Strategies} from "../../sections/Strategies";
import {Affiliate} from "../../sections/Affiliate";
import { DashboardFooter } from "../../../footers/DashboardFooter/DashboardFooter";
import { fetchUserDataRequest } from '../../../../redux/slices/userDataSlice'

export const RegularUser = () => {
  const [activeSection, setActiveSection] = useState("account"); // Текущее активное меню
  const userId = useSelector((state) => state.login?.user.id);
  const dispatch = useDispatch();
  const navigate = useNavigate();

    useEffect(() => {
      if(userId) {
        dispatch(fetchUserDataRequest(userId))
      }
      
  }, [userId, dispatch, navigate]);


  // Функция для рендера активного раздела
  const renderActiveSection = () => {
    switch (activeSection) {
      case "account":
        return <Account />;
      case "demo":
        return <Demo />;
      case "trade":
        return <Trade />;
      case "strategies":
        return <Strategies />;
      case "affiliate":
        return <Affiliate />;
      default:
        return <Account />;
    }
  };

  return (
    <>
      <div className={styles.layoutСontainer}>
        <DashboardHeader />
          <DashboardLayout
            sidebar={
              <Sidebar activeSection={activeSection} setActiveSection={setActiveSection} />
            }
          >
            {/* Рендер активного раздела */}
            {renderActiveSection()}
          </DashboardLayout>
        <DashboardFooter/>
      </div>
    </>
  );
};
