import React, { useEffect, useState } from "react";
import "./StockBackground.css";

const StockBackground = () => {
  // Состояние для хранения массива свечей
  const [candles, setCandles] = useState([]);

  // Эффект, который запускается при монтировании компонента
  useEffect(() => {
    // Интервал для генерации новых свечей каждые 2 секунды
    const candleInterval = setInterval(generateCandles, 2000);

    // Очистка интервалов при размонтировании компонента
    return () => {
      clearInterval(candleInterval);
    };
  }, []);

  // Функция для генерации новых свечей
  const generateCandles = () => {
    // Создаем массив из 5 новых свечей
    const newCandles = Array.from({ length: 1 }, () => ({
      id: Math.random(), // Уникальный идентификатор свечи
      x: Math.random() * window.innerWidth, // Горизонтальная позиция (случайное значение от 0 до ширины экрана)
      y: Math.random() * window.innerHeight, // Вертикальная позиция (случайное значение от 0 до ширины экрана)
      bodyHeight: Math.random() * 50 + 30, // Высота тела свечи (от 10px до 80px)
      shadowTopHeight: Math.random() * 125, // Высота верхней тени (от 0px до 125px)
      shadowBottomHeight: Math.random() * 125, // Высота нижней тени (от 0px до 75px)
      bullish: Math.random() > 0.5, // Флаг типа свечи (true — рост, false — падение)
    }));

    // Добавляем новые свечи в массив состояния
    setCandles((prevCandles) => [...prevCandles, ...newCandles]);

    // Через 12 секунд удаляем старые свечи, оставляя только последние 50
    setTimeout(() => {
      setCandles((prevCandles) => prevCandles.slice(-50));
    }, 3000);
  };

  return (
    // Корневой контейнер для фона
    <div className="stock-background">
      {/* Основные бегущие строки */}
      <div className="stock-ticker primary-ticker">
        <span>AAPL: $192.55 ▲</span>
        <span>TSLA: $265.32 ▼</span>
        <span>AMZN: $134.17 ▲</span>
        <span>NVDA: $480.91 ▲</span>
      </div>

      {/* Второстепенные бегущие строки */}
      <div className="stock-ticker secondary-ticker">
        <span>GSPC: 4,567.23 ▲</span>
        <span>EUR/USD: 1.0802 ▼</span>
        <span>GOLD: $1,845.30 ▲</span>
      </div>

      {/* Третичные бегущие строки */}
      <div className="stock-ticker tertiary-ticker">
        <span>BTC/USD: 63,420 ▲</span>
        <span>MSFT: $330.11 ▼</span>
        <span>DJI: 39,123.45 ▲</span>
      </div>

      {/* Контейнер для японских свечей */}
      <div className="candle-container">
        {/* Рендерим каждую свечу из массива candles */}
        {candles.map((candle) => (
          // Каждая свеча имеет уникальный ключ и стилизацию
          <div
            key={candle.id} // Уникальный идентификатор для React
            className={`candle ${candle.bullish ? "bullish" : "bearish"}`} // Класс для цвета свечи
            style={{
              left: `${candle.x}px`, // Горизонтальная позиция
              top: `${candle.y}px`, // Вертикальная позиция
            }}
          >
            {/* Верхняя тень свечи */}
            <div
              className="candle-shadow-top" // Класс для стилей верхней тени
              style={{
                height: `${candle.shadowTopHeight}px`, // Высота верхней тени
              }}
            ></div>

            {/* Тело свечи */}
            <div
              className="candle-body" // Класс для стилей тела свечи
              style={{
                height: `${candle.bodyHeight}px`, // Высота тела свечи
              }}
            ></div>

            {/* Нижняя тень свечи */}
            <div
              className="candle-shadow-bottom" // Класс для стилей нижней тени
              style={{
                height: `${candle.shadowBottomHeight}px`, // Высота нижней тени
              }}
            ></div>
          </div>
        ))}
      </div>
    </div>
  );
};

export default StockBackground;
