import React, { useState } from 'react';
import DatePicker from 'react-datepicker';
import styles from './DateRangePicker.module.css';
import 'react-datepicker/dist/react-datepicker.css';
import { format } from 'date-fns';
import { ru } from 'date-fns/locale';

export const DateRangePicker = ({ onChange }) => {
  const [startDate, setStartDate] = useState(null);
  const [endDate, setEndDate] = useState(null);

  const handleChange = (dates) => {
    const [start, end] = dates;
    setStartDate(start);
    setEndDate(end);

    if (onChange) {
      onChange({ startDate: start, endDate: end });
    }
  };

  // Форматируем текущую дату как "Май 2025"
  const todayPlaceholder = format(new Date(), 'LLLL yyyy', { locale: ru });

  return (
    <div className={styles.wrapper}>
      <DatePicker
        selected={startDate}
        onChange={handleChange}
        startDate={startDate}
        endDate={endDate}
        selectsRange
        placeholderText={todayPlaceholder}
        dateFormat="dd.MM.yyyy"
        className={styles.input}
        calendarClassName={styles.calendar}
        locale={ru} // Обязательно указываем русскую локаль
      />
    </div>
  );
};