/**
 * Рассчитывает риск/ревард на основе данных о сделках.
 *
 * Risk/Reward Ratio = Средняя прибыль от успешных сделок / Средний убыток от убыточных сделок.
 *
 * @param {Array} trades - Массив объектов с данными о сделках, содержащими ключ "profit" (прибыль/убыток).
 * @returns {number} - Значение риск/ревард.
 */
export const calculateRiskReward = (trades) => {
  // Средняя прибыль от успешных сделок
  const averageProfit =
    trades
      .filter((trade) => trade.profit > 0) // Только прибыльные сделки
      .reduce((sum, trade) => sum + trade.profit, 0) /
    Math.max(1, trades.filter((trade) => trade.profit > 0).length);

  // Средний убыток от убыточных сделок
  const averageLoss =
    trades
      .filter((trade) => trade.profit < 0) // Только убыточные сделки
      .reduce((sum, trade) => sum + Math.abs(trade.profit), 0) /
    Math.max(1, trades.filter((trade) => trade.profit < 0).length);

  // Расчет риск/ревард
  return averageProfit / averageLoss;
};
