import React, { useState } from "react";
import { calculateSharpeRatio } from "../analytics";
import { calculateProfitFactor } from "../analytics";
import { calculateRiskReward } from "../analytics";
import { calculateEquityCurve } from "../analytics";
import styles from "./IndicatorMenu.module.css";

export const IndicatorMenu = ({ onIndicatorChange }) => {
  
  const [isMenuOpen, setIsMenuOpen] = useState(false);
  // Открываем меню при наведении
  const handleMouseEnter = () => setIsMenuOpen(true);

  // Закрываем меню, когда курсор уходит
  const handleMouseLeave = () => setIsMenuOpen(false);

  const indicators = [
    { name: "Кривая доходности", func: calculateEquityCurve },
    { name: "Коэффициент Шарпа", func: calculateSharpeRatio },
    { name: "Профит-фактор", func: calculateProfitFactor },
    { name: "Риск/Ревард", func: calculateRiskReward },
  ];

  return (
    <div
      className={styles.menu_wrapper}
      onMouseEnter={handleMouseEnter} // Открытие меню при наведении
      onMouseLeave={handleMouseLeave} // Закрытие меню при уходе курсора
    >
      <button
        className={`${styles.button} ${isMenuOpen ? styles.active : ""}`}
        aria-expanded={isMenuOpen}
        aria-controls="range-list"
      >
        <span className={styles.button_text}>Показатели ТС</span>
      </button>
      <ul className={styles.menu} id="range-list" aria-hidden={!isMenuOpen}>
        {indicators.map((indicator, index) => (
          <li key={index} className={styles.menu_item}>
            <button
              className={`${styles.menu_link}`}
              tabIndex={isMenuOpen ? 0 : -1}
              onClick={() => {
                onIndicatorChange(indicator.func);
              }}
            >
              {indicator.name}
            </button>
          </li>
        ))}
      </ul>
    </div>
  );
};
