import React, { useState, useEffect } from "react";
import styles from "./TradingStrategy.module.css"; // Предполагается, что стили импортированы
import { StrategyMenu } from "../StrategyMenu";
import { RangeMenu } from "../RangeMenu";
import { TradingStrategiesChart } from "../TradingStrategiesChart";
import { Histogram } from "../Histogram";
import { IndicatorMenu } from "../IndicatorMenu";


export const TradingStrategy = ({ data }) => {

  const [selectedIndicatorFunc, setSelectedIndicatorFunc] = useState(() => () => {});
  // Получаем список стратегий с их именами
  const tradingStrategyNames = Object.entries(data).filter(
    ([, value]) => value.name,
  );

  const [selectedMetric, setSelectedMetric] = useState("equity");

  // Состояние для выбранной стратегии
  const [selectedStrategy, setSelectedStrategy] = useState(
    tradingStrategyNames[0][1].name,
  );
  const [tradingStrategy, setTradingStrategy] = useState(
    data[tradingStrategyNames[0][0]],
  );

  // Состояние для данных графика
  const [chartData, setChartData] = useState([]);
  const [timeframeData, setTimeframeData] = useState(
    Object.keys(tradingStrategy.profit),
  );
  const [selectedRange, setSelectedRange] = useState("W1");

  // Форматирование данных для графика
  const formatChartData = (profitData) =>
    Object.entries(profitData)
      .map(([date, value]) => ({
        name: date,
        pv: Math.round(value * 100) / 100, // Округление до 2 знаков после запятой
      }))
      .sort((a, b) => a.name.localeCompare(b.name));

  // Инициализация данных графика при монтировании компонента
  useEffect(() => {
    const initialData = formatChartData(
      data[tradingStrategyNames[0][0]].profit.W1,
    );
    setChartData(initialData);
  }, [data]);

  // Обработчик выбора стратегии
  const handleStrategyChange = (strategy) => {
    const [strategyKey, strategyData] = strategy;
    setTradingStrategy(data[strategyKey]);
    setTimeframeData(Object.keys(strategyData.profit));
    setSelectedStrategy(strategyData.name);
    setSelectedRange("W1"); // Сбрасываем диапазон на W1 при смене стратегии
    const formattedData = formatChartData(strategyData.profit.W1);
    setChartData(formattedData);
  };

  // Обработчик выбора диапазона
  const handleRangeChange = (range) => {
    const formattedData = formatChartData(tradingStrategy.profit[range]);
    setChartData(formattedData);
    setSelectedRange(range);
  };

  const handleIndicatorChange = (indicatorFunc) => {
    console.log("change")
    setSelectedIndicatorFunc(() => indicatorFunc); // сохраняем функцию в состояние
  };



  return (
    <div className={styles.trading_strategy_container}>
      {/* Меню выбора стратегии */}
      <div className={styles.menu_container}>
        <StrategyMenu
          strategies={tradingStrategyNames}
          selectedStrategy={selectedStrategy}
          onStrategyChange={handleStrategyChange}
        />

        {/* Меню выбора диапазона */}
        <RangeMenu
          ranges={timeframeData}
          selectedRange={selectedRange}
          onRangeChange={handleRangeChange}
        />
        {/* Меню выбора показателя торговой стратегии */}
        <IndicatorMenu
          ranges={timeframeData}
          selectedRange={selectedRange}
          onIndicatorChange={handleIndicatorChange}
        />
      </div>
      {/* Графики и статистика */}
      <TradingStrategiesChart 
        chartData={chartData}
        selectedMetric={selectedMetric}
        indicatorFunc={selectedIndicatorFunc}
      />
      <Histogram data={chartData} />
    </div>
  );
};
