/**
 * Рассчитывает кривую доходности (Equity Curve), масштабированную под диапазон pv.
 *
 * @param {Array} data - Массив с полем pv.
 * @returns {Array} - Массив с добавленным полем normalizedEquity.
 */
export const calculateEquityCurve = (data) => {
  if (!data || data.length === 0) return [];

  const initialValue = data[0].pv;

  return data.map((entry) => {
    const cumulativeReturn = (entry.pv - initialValue) / initialValue;
    return {
      ...entry,
      equity: cumulativeReturn * 100, // В процентах
    };
  });
};