import { useEffect, useState, useRef } from "react";
import { useDispatch, useSelector } from "react-redux";
import styles from './SystemStatus.module.css';
import { fetchUserDataRequest } from '../../../../../redux/slices/userDataSlice';

export const SystemStatus = () => {
  const dispatch = useDispatch();
  const userId = useSelector((state) => state.login?.user.id);
  const autofollow = useSelector((state) => state.userData.autofollow);
  const startTime = useSelector((state) => state.userData.startTime);

  const [time, setTime] = useState(0);
  const intervalRef = useRef(null);
  const statusRef = useRef(autofollow); // для отслеживания изменений

  const SYNC_INTERVAL_MINUTES = 2; // синхронизация каждые 2 минуты

    // Запрос данных пользователя при монтировании
  useEffect(() => {
    if (userId) {
      dispatch(fetchUserDataRequest(userId));
    }
  }, [dispatch, userId]);

  console.log('startTime', startTime)

  // Подсчёт времени
  useEffect(() => {
    if (autofollow && startTime) {
      const startTimestamp = new Date(startTime).getTime();
      const now = Date.now();
      setTime(Math.floor((now - startTimestamp) / 1000));

      intervalRef.current = setInterval(() => {
        setTime((prev) => prev + 1);
      }, 1000);
    } else {
      if (intervalRef.current) {
        clearInterval(intervalRef.current);
        intervalRef.current = null;
      }
    }

    return () => {
      if (intervalRef.current) {
        clearInterval(intervalRef.current);
      }
    };
  }, [autofollow, startTime]);


  // Форматирование времени
  const formatTime = (totalSeconds) => {
    const hours = Math.floor(totalSeconds / 3600);
    const minutes = Math.floor((totalSeconds % 3600) / 60);
    const seconds = totalSeconds % 60;
    return `${hours} час ${minutes} мин ${seconds} сек`;
  };

  return (
    <div className={styles.container}>
      <div className={styles.header}>
        <h2 className={styles.tytle}>
          Статус системы: {autofollow ? 'Торгуется' : 'Приостановлено'}
        </h2>
        <h3 className={styles.workTime}>
          Время работы: {formatTime(time)}
        </h3>
      </div>
    </div>
  );
};