import { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import styles from './AccountInformation.module.css'

export const AccountInformation = ({ onSettingsClick, accountNumber, accountName }) => {
  const [demoAccountNumber, setDemoAccountNumber] = useState(null);
  const navigate = useNavigate();

  useEffect(() => {
    setDemoAccountNumber(accountNumber); // обновляем при изменении пропа
  }, [accountNumber]);

  useEffect(() => {
    const storedAccountNumber = localStorage.getItem({accountName});
    setDemoAccountNumber(storedAccountNumber);
  }, []);

  const handleChange = () => {
    console.log('accountName', accountName)
    localStorage.removeItem({accountName});
    setDemoAccountNumber(null); // Обновляем состояние, чтобы UI отразил изменения
  
    // Вызовем функцию из родителя
    if (onSettingsClick) {
      onSettingsClick();
    }
  };


  return (
    <div className={styles.container}>
      <div className={styles.brokerInformation}>
        <div className={styles.brokerName}>
          Брокер Trade Forex
        </div>
        <div className={styles.brokerAccount}>
          Счет {demoAccountNumber}
        </div>
      </div>
      <div className={styles.settingsContainer}>
        <button className={styles.settings} onClick={handleChange}>настроить</button>
      </div>
    </div>
  );
};
