import { useState } from "react";
import styles from './Strategys.module.css'

// Пример списка стратегий
const strategyOptions = [
  {
    title: 'Сбалансированная',
    description: 'Доходность до 5% в месяц',
    risk: 'низкий',
  },
  {
    title: 'Агрессивная',
    description: 'Доходность до 15% в месяц',
    risk: 'высокий',
  },
  {
    title: 'Консервативная',
    description: 'Доходность до 2% в месяц',
    risk: 'очень низкий',
  },
];

export const Strategys = () => {
  const [isModalOpen, setIsModalOpen] = useState(false); // Состояние модального окна
  const [selectedStrategy, setSelectedStrategy] = useState(strategyOptions[0]); // Стратегия по умолчанию

  const openModal = () => setIsModalOpen(true);
  const closeModal = () => setIsModalOpen(false);

  const handleStrategySelect = (strategy) => {
    setSelectedStrategy(strategy);
    closeModal();
  };

  return (
    <div className={styles.container}>
      <div className={styles.header}>
        <h2 className={styles.tytle}>Выбранная стратегия</h2>
      </div>

      <div className={styles.strategy}>
        <div className={styles.strategyIcon}>
          <img src='/icon/strategiesColor.svg' alt='Выбранная стратегия' />
        </div>
        <div className={styles.strategyInformation}>
          <div className={styles.strategyHeader}>
            <h3 className={styles.strategyTitle}>{selectedStrategy.title}</h3>
            <button className={styles.strategyChange} onClick={openModal}>
              Изменить
            </button>
          </div>
          <div className={styles.strategyProfitability}>
            <div className={styles.strategyDescription}>{selectedStrategy.description}</div>
            <div className={styles.strategyRisk}>Риск: {selectedStrategy.risk}</div>
          </div>
        </div>
      </div>

      {isModalOpen && (
        <div className={styles.modalOverlay}>
          <div className={styles.modal}>
            <h3>Выберите стратегию</h3>
            <ul className={styles.strategyList}>
              {strategyOptions.map((strategy, index) => (
                <li
                  key={index}
                  className={styles.strategyItem}
                  onClick={() => handleStrategySelect(strategy)}
                >
                  <strong>{strategy.title}</strong>
                  <div>{strategy.description}</div>
                  <div>Риск: {strategy.risk}</div>
                </li>
              ))}
            </ul>
            <button onClick={closeModal} className={styles.closeButton}>
              Отмена
            </button>
          </div>
        </div>
      )}
    </div>
  );
};