import React, { useState, useEffect } from "react";
import { Tooltip, PieChart, Pie, Cell, Sector } from "recharts";
import styles from "./Tools.module.css"; // Подключен CSS-модуль

export const Tools = () => {
  const [selectedPair, setSelectedPair] = useState(null);
  const [activeIndex, setActiveIndex] = useState(null);
  const [prevValue, setPrevValue] = useState(null);

  useEffect(() => {
    if (selectedPair) {
      setPrevValue(selectedPair.value);
    }
  }, [selectedPair]);

  const handleMouseEnter = (pair, index) => {
    setSelectedPair(pair);
    setActiveIndex(index);
  };

  const handleMouseLeave = () => {
    setSelectedPair(null);
    setActiveIndex(null);
  };

  const COLORS = [
    "#FF4500",
    "#FF6347",
    "#FFD700",
    "#FFA500",
    "#FF1493",
    "#00FFFF",
    "#7FFF00",
    "#FF4040",
    "#FF8C00",
    "#FF69B4",
  ];

  const currencyPair = [
    { name: "EUR/USD", value: 12 },
    { name: "USD/JPY", value: 15 },
    { name: "GBP/USD", value: 7 },
    { name: "USD/CHF", value: 10 },
    { name: "AUD/USD", value: 5 },
    { name: "USD/CAD", value: 6 },
    { name: "NZD/USD", value: 3 },
    { name: "BRN/USD", value: 25 },
    { name: "XAU/USD", value: 11 },
    { name: "XAG/RUB", value: 7 },
  ];

  const currencyPairWithColors = currencyPair.map((pair, index) => ({
    ...pair,
    color: COLORS[index % COLORS.length],
  }));

  const defs = (
    <defs>
      <filter id="glow" x="-50%" y="-50%" width="200%" height="200%">
        <feGaussianBlur stdDeviation="3.5" result="coloredBlur" />
        <feMerge>
          <feMergeNode in="coloredBlur" />
          <feMergeNode in="SourceGraphic" />
        </feMerge>
      </filter>
      <filter id="glow-active" x="-50%" y="-50%" width="200%" height="200%">
        <feGaussianBlur stdDeviation="6" result="coloredBlur" />
        <feMerge>
          <feMergeNode in="coloredBlur" />
          <feMergeNode in="SourceGraphic" />
        </feMerge>
      </filter>
    </defs>
  );

  const renderActiveShape = (props) => {
    const { cx, cy, innerRadius, outerRadius, startAngle, endAngle, fill } =
      props;

    return (
      <g>
        <Sector
          cx={cx}
          cy={cy}
          innerRadius={innerRadius}
          outerRadius={outerRadius + 8}
          startAngle={startAngle}
          endAngle={endAngle}
          fill={fill}
          filter="url(#glow-active)"
        />
      </g>
    );
  };

  return (
    <div className={styles.tool_card}>
      <h3 className={styles.tool_title}>Инструменты</h3>
      <div className={styles.pie_chart}>
        <PieChart width={220} height={240}>
          {defs}
          <Pie
            data={currencyPairWithColors}
            cx="50%"
            cy="50%"
            innerRadius={80}
            outerRadius={95}
            dataKey="value"
            stroke="none"
            paddingAngle={2}
            activeIndex={activeIndex}
            activeShape={renderActiveShape}
            onMouseLeave={handleMouseLeave}
            onMouseEnter={(data, index) =>
              handleMouseEnter(data.payload, index)
            }
          >
            {currencyPairWithColors.map((pair, index) => (
              <Cell
                key={`cell-${index}`}
                fill={pair.color}
                filter="url(#glow)"
              />
            ))}
          </Pie>

          {/* Старое значение (улетает влево) */}
          {prevValue !== "100" && (
            <text
              x="50%"
              y="50%"
              textAnchor="middle"
              dominantBaseline="central"
              fill="#ffffff"
              fontSize={selectedPair ? "24px" : "16px"}
              fontWeight="500"
              className={`${styles.text} ${selectedPair ? styles.textEnter : styles.textDefault}`}
            >
              {selectedPair ? `${selectedPair.value}%` : "100%"}
            </text>
          )}

          {/* Новое значение (влетает справа) */}
          {selectedPair && (
            <text
              x="50%"
              y="50%"
              textAnchor="middle"
              dominantBaseline="central"
              className={`${styles.text} ${styles.textEnter}`}
              key={`text-enter-${selectedPair.value}`}
            >
              {selectedPair.value}%
            </text>
          )}

          {/*<Tooltip />*/}
        </PieChart>

        <div className={styles.deposit_distribution}>
          <ul>
            {currencyPairWithColors.map((pair, index) => (
              <li
                key={index}
                className={styles.deposit_distribution_title}
                onMouseEnter={() => handleMouseEnter(pair, index)}
                onMouseLeave={handleMouseLeave}
              >
                <div
                  className={styles.deposit_distribution_color}
                  style={{
                    background: pair.color,
                    boxShadow: `0 0 6px ${pair.color}, 0 0 12px ${pair.color}`,
                  }}
                ></div>
                {pair.name} {pair.value}
                {"%"}
              </li>
            ))}
          </ul>
        </div>
      </div>
    </div>
  );
};
