import React, { useState }  from 'react'
import { Efficiency } from '../Efficiency'

import styles from './Deposit.module.css'
import { AutoTracking } from '../AutoTracking/AutoTracking';
import { useSelector } from 'react-redux';

export const Deposit = ({statistics, real}) => {
  const [activeProfit, setActiveProfit] = useState('today'); // 'today' или 'total'
  const [isAutoTrackingEnabled, setIsAutoTrackingEnabled] = useState(false);
  const userData = useSelector((state) => state.userData?.data);
  console.log('userData', userData)

  const handleSelect = (type) => {
    setActiveProfit(type);
  };

  const handleToggleChange = (value) => {
    setIsAutoTrackingEnabled(value);
    console.log('Новое значение из дочернего компонента:', value);
  };

  const profitAmount = activeProfit === 'today' ? (userData ? userData.profitToday : 'N/A') : (userData ? userData.profitTotal : 'N/A');

  let profitToday = 'N/A'
  let profitTotal = 'N/A'

  if (userData) {

  profitToday = userData.profitToday / userData.balance * 100;
  profitToday = Math.floor(profitToday * 100) / 100; // Оставляем 2 знака без округления

  profitTotal = userData.profitTotal / userData.balance * 100;
  profitTotal = Math.floor(profitTotal * 100) / 100;
  }

  return (
    <div className={styles.container}>
      <AutoTracking onToggleChange={handleToggleChange} />
      <div className={styles.header}>
        <h2 className={styles.tytle}>Депозит {real ? '(Основной)' : null}</h2>
        <h3 className={styles.inUse}>Задействовано: {userData ? userData.partInTrade : 'N/A'}%</h3>
      </div>

      <div className={styles.depositInformation}>
        <h3 className={styles.depositCurrency}>USD</h3>
        <div className={styles.depositVolume}>{userData ? userData.balance : 'N/A'}$</div> 
      </div>

      <div className={styles.profitInformation}>
        <div
          className={`${styles.profitToday} ${
            activeProfit === 'today' ? styles.active : styles.inactive
          }`}
          onClick={() => handleSelect('today')}
        >
          <span className={styles.profitTodayTitle}>Сегодня</span>
          <span className={styles.profitTodayValue}>+{profitToday}%</span>
        </div>

        <div
          className={`${styles.profitTotal} ${
            activeProfit === 'total' ? styles.active : styles.inactive
          }`}
          onClick={() => handleSelect('total')}
        >
          <span className={styles.profitTodayTitle}>Всего</span>
          <span className={styles.profitTodayValue}>{profitTotal}%</span>
        </div>
      </div>

      <div className={styles.profitАmount}>{profitAmount}</div>
      {statistics ?       
      <div className={styles.statistics}>
        <Efficiency 
          title={'Количество трейдов'}
          view={'green'}
          value={'3'}
        />
        <Efficiency 
          title={'Прибыль/убыток'}
          view={'green'}
          value={'N/A'}
        />
        <Efficiency 
          title={'Коэффициент Шарпа'}
          view={'green'}
          value={'N/A'}
        />
      </div> : null}

    </div>
  );
};