import React, { useRef, useEffect } from "react";
import styles from "./InvestorCapital.module.css";

export const InvestorCapital = ({ data }) => {
  const capital = data.general_stats;
  const scrollRef = useRef(null);

  useEffect(() => {
    const el = scrollRef.current;
    if (!el) return;

    const onWheel = (e) => {
      if (e.deltaY === 0) return;
      e.preventDefault();
      el.scrollLeft += e.deltaY; // вертикальное колесо -> горизонтальный скролл
    };

    el.addEventListener("wheel", onWheel, { passive: false });

    return () => {
      el.removeEventListener("wheel", onWheel);
    };
  }, []);

  return (
    <div className={styles.capital_card}>
      <h3>Капитал инвестора</h3>
      <div className={styles.scroll_container} ref={scrollRef}>
        <div className={styles.capital_item}>
          <span className={styles.label}>В управлении:</span>
          <span className={styles.value}>{"???????"} ₽</span>
        </div>
        <div className={styles.capital_item}>
          <span className={styles.label}>Общий капитал:</span>
          <span className={styles.value}>{capital.finances_total} ₽</span>
        </div>
        <div className={`${styles.capital_item} ${styles.earned}`}>
          <span className={styles.label}>Заработано:</span>
          <span className={styles.value}>{capital.profit_total} ₽</span>
        </div>
        <div className={`${styles.capital_item} ${styles.earned}`}>
          <span className={styles.label}>Заработано по партнёрке:</span>
          <span className={styles.value}>{"???????"} ₽</span>
        </div>
        <div className={`${styles.capital_item} ${styles.earned}`}>
          <span className={styles.label}>Оборот:</span>
          <span className={styles.value}>{"???????"} ₽</span>
        </div>
      </div>
    </div>
  );
};